-- HUBC 5k erg test, Mon 28 Sep 2026 -- typed from the squad's sheet
-- ("HUBC Ergs 26_27 - 9_28 5k.pdf"): 26 on Concert2 ergs + Joe Baker on the RP3.
-- Skipped on purpose: the bike and RX rows (not a 5k on an erg; several have no
-- time) and Charles Richards (no time).
--
-- These rowers have no accounts yet, so their rows carry a fixed id starting
-- 'ae6c0000-' (made from the name) instead of an account id. That needs the link
-- to auth.users dropped; the board only ever reads athlete_name. The app does not
-- offer a profile page for these ids. Safe to re-run.
alter table public.varsity_results drop constraint if exists varsity_results_athlete_id_fkey;
delete from public.varsity_results where day_key = '2026-8-28-PM' and athlete_id::text like 'ae6c0000-%';
